<?php
declare(strict_types=1);
use App\Service\{ReservationPolicyService as Policies,ReservationTerms,BillingService,BookingClock,BookingService,ManagementService,StaffReservationService};
if(!Policies::enabled($t->pdo))throw new RuntimeException('Explicitly prepare isolated B5 first.');
function pclock($t,string $when):BookingClock{return new BookingClock($t->pdo,fn()=>new DateTimeImmutable($when,new DateTimeZone('Asia/Manila')));}
function pservice($t,string $when):Policies{return new Policies($t->pdo,pclock($t,$when));}
function pmoney($t,array $actor,int $id,string $action,int $amount=0,?string $when=null,?string $key=null):array{
 $clock=$when?pclock($t,$when):new BookingClock($t->pdo);$s=new BillingService($t->pdo,$clock);$q=$s->quote($actor,$id);
 $hex=bin2hex(random_bytes(16));$key??=substr($hex,0,8).'-'.substr($hex,8,4).'-'.substr($hex,12,4).'-'.substr($hex,16,4).'-'.substr($hex,20);
 $data=$action==='review_cancellation'?['reason'=>'Manager reviewed original policy and actual receipts']:($action==='finalize'?[]:['amount_cents'=>$amount,'method'=>'cash','reason'=>'Isolated policy record']);
 return $s->mutate($actor,$id,$action,$q['revision'],$key,$data);
}
function pcancel($t,$b,string $when,string $outcome='cancelled'):array{return (new BookingService($t->pdo,pclock($t,$when)))->cancel((int)$b['r']['id'],'Policy boundary cancellation',null,$outcome);}
if(defined('POLICY_FIXTURE_ONLY'))return;
$t->test('B5 confirmation stores full accepted terms and fixed original deadline',function($t){$b=b4book($t);$p=Policies::read($t->pdo,(int)$b['r']['id']);$t->assert($p['accepted_json']['policy_version']===ReservationTerms::VERSION&&count($p['accepted_json']['policy'])===8&&$p['accepted_at']!==null);});
$t->test('B5 same-day VIP2500 base forfeits while300 extras remain separately refundable',function($t){$b=b4book($t,'bv_vip',16);$a=b4actor($t);$id=(int)$b['r']['id'];pmoney($t,$a,$id,'advance',250000);pmoney($t,$a,$id,'extra_receipt',30000);pcancel($t,$b,$t->date.' 09:00:00');$q=(new BillingService($t->pdo,new BookingClock($t->pdo)))->quote($a,$id);$t->assert($q['policy']['forfeited_base_cents']===250000&&$q['policy_money']['net_extra_cents']===30000&&$q['due_cents']===0&&$q['credit_applied_cents']===0);$t->expectError('review_required',fn()=>pmoney($t,$a,$id,'refund_extra',30000));pmoney($t,$a,$id,'review_cancellation');$t->expectError('invalid_amount',fn()=>pmoney($t,$a,$id,'refund_base',1));pmoney($t,$a,$id,'refund_extra',30000);$q=pmoney($t,$a,$id,'finalize')['bill'];$t->assert($q['received_cents']===250000&&$q['status']==='finalized');});
$t->test('B5 unpaid cancellation fabricates no receipt/refund/forfeiture',function($t){$b=b4book($t);$id=(int)$b['r']['id'];pcancel($t,$b,$t->date.' 09:00:00');$p=Policies::read($t->pdo,$id);$t->assert($p['forfeited_base_cents']===0&&$t->count('billing_events')===0&&$t->count('policy_money_events')===0);});
$t->test('B5 prior-day late cancellation does not become same-day forfeiture',function($t){$b=b4book($t);$a=b4actor($t);$id=(int)$b['r']['id'];pmoney($t,$a,$id,'advance',50000);$when=(new DateTimeImmutable($b['r']['starts_at']))->modify('-23 hours')->format('Y-m-d H:i:s');pcancel($t,$b,$when);$p=Policies::read($t->pdo,$id);$t->assert($p['terminal_json']['late']===true&&$p['terminal_json']['same_day']===false&&$p['forfeited_base_cents']===0);pmoney($t,$a,$id,'review_cancellation');pmoney($t,$a,$id,'refund_base',50000);$t->assert(pmoney($t,$a,$id,'finalize')['bill']['received_cents']===0);});
$t->test('B5 timely private cancellation is inclusive24h and rejects a second later',function($t){$b=b4book($t);[$s,$token]=b4link($t,$b);$deadline=(new DateTimeImmutable($b['r']['starts_at']))->modify('-24 hours');$t->expectError('cutoff_passed',fn()=>(new ManagementService($t->pdo,pclock($t,$deadline->modify('+1 second')->format('Y-m-d H:i:s'))))->cancel($b['r']['code'],$token,1));(new ManagementService($t->pdo,pclock($t,$deadline->format('Y-m-d H:i:s'))))->cancel($b['r']['code'],$token,1);$t->assert(Policies::read($t->pdo,(int)$b['r']['id'])['status']==='cancelled');});
$t->test('B5 no-show is not a forfeiture and only actual reviewed refunds resolve it',function($t){$b=b4book($t);$id=(int)$b['r']['id'];$a=b4actor($t);pmoney($t,$a,$id,'advance',50000);$count=pservice($t,$t->date.' 10:15:00')->reconcile();$p=Policies::read($t->pdo,$id);$t->assert($count===1&&$p['status']==='no_show'&&$p['forfeited_base_cents']===0);$t->expectError('refund_pending',fn()=>pmoney($t,$a,$id,'finalize'));pmoney($t,$a,$id,'review_cancellation');pmoney($t,$a,$id,'refund_base',50000);$t->assert(pmoney($t,$a,$id,'finalize')['bill']['received_cents']===0);});
$t->test('B5 release before/at15min is locked and repeated release increments history once',function($t){$b=b4book($t);$t->assert(pservice($t,$t->date.' 10:14:59')->reconcile()===0);$t->assert(pservice($t,$t->date.' 10:15:00')->reconcile()===1);$t->assert(pservice($t,$t->date.' 10:16:00')->reconcile()===0);$t->assert((int)$t->pdo->query("SELECT no_show_count FROM guests")->fetchColumn()===1&&$t->pdo->query('SELECT released_at FROM reservation_tables')->fetchColumn()!==null);});
$t->test('B5 occupied parties are never automatically released',function($t){$b=b4book($t,'bv_standard',2,100000);$a=b4actor($t);(new StaffReservationService($t->pdo,b4clock($t,'10:14:59')))->transition($a,$b['r']['code'],1,'seat','Arrived within grace');$t->assert(pservice($t,$t->date.' 10:30:00')->reconcile()===0&&$t->pdo->query('SELECT status FROM reservations')->fetchColumn()==='seated');});
$t->test('B5 at15min seating fails without creating provisional food/tickets',function($t){$b=b4book($t,'bv_standard',2,100000);$t->expectError('arrival_window_closed',fn()=>(new StaffReservationService($t->pdo,b4clock($t,'10:15:00')))->transition(b4actor($t),$b['r']['code'],1,'seat','Too late'));$t->assert($t->count('orders')===0&&$t->count('kitchen_tickets')===0);});
$t->test('B5 received extras reduce the served bill without using base credit',function($t){$b=b4book($t,'bv_vip',16);$id=(int)$b['r']['id'];$a=b4actor($t);pmoney($t,$a,$id,'extra_receipt',30000);(new StaffReservationService($t->pdo,b4clock($t,'10:00:00')))->transition($a,$b['r']['code'],1,'seat','Arrived');$q=(new BillingService($t->pdo,new BookingClock($t->pdo)))->quote($a,$id);$t->assert($q['due_cents']===$q['food_cents']&&$q['credit_applied_cents']===0);});
$t->test('B5 live same-day base refund cannot bypass cancellation forfeiture',function($t){$b=b4book($t);$id=(int)$b['r']['id'];$a=b4actor($t);pmoney($t,$a,$id,'advance',50000);$t->expectError('refund_not_eligible',fn()=>pmoney($t,$a,$id,'refund_base',50000,$t->date.' 09:00:00'));});
$t->test('B5 guest replacement needs exact new-fee terms and preserves earlier deadline',function($t){$b=b4book($t);[$s,$token]=b4link($t,$b);$next=(new DateTimeImmutable($t->date))->modify('+1 day')->format('Y-m-d');$t->expectError('policy_acceptance_required',fn()=>$s->modify($b['r']['code'],$token,1,$next,'10:00',5,'bv_family',null,null,''));$ack=['version'=>ReservationTerms::VERSION]+App\Service\BillingFees::assess('bv_family',5);$s->modify($b['r']['code'],$token,1,$next,'10:00',5,'bv_family',null,null,'',$ack);$p=Policies::read($t->pdo,(int)$b['r']['id']);$t->assert($p['deadline_at']===(new DateTimeImmutable($b['r']['starts_at']))->modify('-24 hours')->format('Y-m-d H:i:s')&&count(App\Service\PreorderService::read($t->pdo,(int)$b['r']['id'])['history'])===1);});
$t->test('B5 funds above replacement fees block change without changing food/booking',function($t){$b=b4book($t,'bv_vip',15);$a=b4actor($t);$id=(int)$b['r']['id'];pmoney($t,$a,$id,'advance',250000);[$s,$token]=b4link($t,$b);$ack=['version'=>ReservationTerms::VERSION]+App\Service\BillingFees::assess('bv_family',5);$t->expectError('refund_required',fn()=>$s->modify($b['r']['code'],$token,1,$t->date,'13:00',5,'bv_family',null,null,'',$ack));$t->assert((int)$t->pdo->query('SELECT version FROM reservations')->fetchColumn()===1);});
$t->test('B5 exact actual-refund replay returns one outflow and changed key payload fails',function($t){$b=b4book($t);$id=(int)$b['r']['id'];$a=b4actor($t);pmoney($t,$a,$id,'advance',50000);pcancel($t,$b,(new DateTimeImmutable($b['r']['starts_at']))->modify('-2 days')->format('Y-m-d H:i:s'));pmoney($t,$a,$id,'review_cancellation');$s=new BillingService($t->pdo,new BookingClock($t->pdo));$q=$s->quote($a,$id);$key='11111111-1111-1111-1111-111111111111';$data=['amount_cents'=>50000,'method'=>'cash','reason'=>'Actual refund test'];$s->mutate($a,$id,'refund_base',$q['revision'],$key,$data);$r=$s->mutate($a,$id,'refund_base',$q['revision'],$key,$data);$t->assert($r['replayed']&&$t->count('policy_money_events')===1);$data['amount_cents']=1;$t->expectError('request_changed',fn()=>$s->mutate($a,$id,'refund_base',$q['revision'],$key,$data));});
$t->test('B5 staff cannot move paid same-day base to bypass forfeiture',function($t){$b=b4book($t);$id=(int)$b['r']['id'];$a=b4actor($t);pmoney($t,$a,$id,'advance',50000);$s=new StaffReservationService($t->pdo,pclock($t,$t->date.' 09:00:00'));$next=(new DateTimeImmutable($t->date))->modify('+1 day')->format('Y-m-d');$input=['code'=>$b['r']['code'],'version'=>1,'date'=>$next,'time'=>'10:00','party_size'=>5,'room_type'=>'bv_family','option'=>['kind'=>'table','id'=>(int)$t->pdo->query('SELECT table_id FROM reservation_tables LIMIT 1')->fetchColumn()],'special_requests'=>'','reason'=>'Manager schedule change','policy_acceptance'=>['version'=>ReservationTerms::VERSION]+App\Service\BillingFees::assess('bv_family',5)];$t->expectError('same_day_fee_protected',fn()=>$s->modify($a,$input));$t->assert((int)$t->pdo->query('SELECT version FROM reservations')->fetchColumn()===1);pcancel($t,$b,$t->date.' 09:00:00');$t->assert(Policies::read($t->pdo,$id)['forfeited_base_cents']===50000);});
$t->test('B5 confirmation recovery reports preserved reschedule deadline',function($t){$b=b4book($t);[$s,$token]=b4link($t,$b);$next=(new DateTimeImmutable($t->date))->modify('+1 day')->format('Y-m-d');$ack=['version'=>ReservationTerms::VERSION]+App\Service\BillingFees::assess('bv_family',5);$s->modify($b['r']['code'],$token,1,$next,'10:00',5,'bv_family',null,null,'',$ack);$r=$t->service->confirm($b['h']['hold_token'],$t->guest,$t->owner,$b['p']);$t->assert($r['cancel_deadline']===Policies::read($t->pdo,(int)$b['r']['id'])['deadline_at'],'Recovery must retain earlier deadline');});
$t->test('B5 staff creation persists governing terms without invented guest acceptance',function($t){$a=b4actor($t);$s=new StaffReservationService($t->pdo,new BookingClock($t->pdo));$result=$s->create($a,['date'=>$t->date,'time'=>'10:00','party_size'=>5,'room_type'=>'bv_family','source'=>'phone','guest'=>$t->guest]);$r=$s->row($result['code']);$p=Policies::read($t->pdo,(int)$r['id']);$event=json_decode($t->pdo->query("SELECT detail_json FROM reservation_policy_events WHERE kind='create'")->fetchColumn(),true);$t->assert($p['accepted_json']===null&&$p['accepted_at']===null&&$event['terms_version']===ReservationTerms::VERSION&&$event['guest_acceptance_recorded']===false);});
$t->test('B5 cross-midnight uses Manila calendar date rather than 24h interval',function($t){$b=b4book($t);$id=(int)$b['r']['id'];$a=b4actor($t);pmoney($t,$a,$id,'advance',50000);$prior=(new DateTimeImmutable($t->date))->modify('-1 day')->format('Y-m-d').' 23:59:59';pcancel($t,$b,$prior);$t->assert(Policies::read($t->pdo,$id)['forfeited_base_cents']===0);});
$t->test('B5 simultaneous seat/release leaves one consistent arrival outcome',function($t){$b=b4book($t,'bv_standard',2,100000);$a=b4actor($t);$jobs=[['op'=>'policy_seat','actor'=>$a,'code'=>$b['r']['code'],'version'=>1,'when'=>$t->date.' 10:14:59'],['op'=>'policy_release','when'=>$t->date.' 10:15:00']];$results=$t->finishWorkers($t->startWorkers($jobs));$status=$t->pdo->query('SELECT status FROM reservations')->fetchColumn();$t->assert(in_array($status,['seated','no_show'],true));$t->assert($t->count('kitchen_tickets')===($status==='seated'?1:0));$t->assert((int)$t->pdo->query("SELECT COUNT(*) FROM reservation_status_history WHERE to_status IN ('seated','no_show')")->fetchColumn()===1);});
$t->test('B5 simultaneous refund keys cannot refund same received funds twice',function($t){$b=b4book($t);$id=(int)$b['r']['id'];$a=b4actor($t);pmoney($t,$a,$id,'advance',50000);pcancel($t,$b,(new DateTimeImmutable($t->date))->modify('-2 days')->format('Y-m-d').' 09:00:00');pmoney($t,$a,$id,'review_cancellation');$q=(new BillingService($t->pdo,new BookingClock($t->pdo)))->quote($a,$id);$job=['op'=>'billing','actor'=>$a,'id'=>$id,'action'=>'refund_base','revision'=>$q['revision'],'data'=>['amount_cents'=>50000,'method'=>'cash','reason'=>'Actual refund race']];$j1=$job+['key'=>'11111111-1111-1111-1111-111111111111'];$j2=$job+['key'=>'22222222-2222-2222-2222-222222222222'];$r=$t->finishWorkers($t->startWorkers([$j1,$j2]));$t->assert(count(array_filter($r,fn($x)=>$x['ok']))===1&&$t->count('policy_money_events')===1);});
$t->test('B5 unavailable scheduled dish rolls back schedule and fee history atomically',function($t){$b=b4book($t);[$s,$token]=b4link($t,$b);$t->pdo->prepare('UPDATE menu_items SET is_available=0 WHERE id=?')->execute([$b['p']['cart'][0]['id']]);$ack=['version'=>ReservationTerms::VERSION]+App\Service\BillingFees::assess('bv_family',5);$t->expectError('item_unavailable',fn()=>$s->modify($b['r']['code'],$token,1,$t->date,'13:00',5,'bv_family',null,null,'',$ack));$t->assert((int)$t->pdo->query('SELECT version FROM reservations')->fetchColumn()===1&&(int)$t->pdo->query("SELECT COUNT(*) FROM reservation_policy_events WHERE kind='change'")->fetchColumn()===0);});
$t->test('B5 replacement cutoff rechecks after real menu lock wait',function($t){$b=b4book($t);[$s,$token]=b4link($t,$b);$deadline=(new DateTimeImmutable($b['r']['starts_at']))->modify('-24 hours');$t->pdo->beginTransaction();$t->pdo->prepare('SELECT id FROM menu_items WHERE id=? FOR UPDATE')->execute([$b['p']['cart'][0]['id']]);$job=['op'=>'policy_modify_cutoff','code'=>$b['r']['code'],'token'=>$token,'date'=>$t->date,'clock_base'=>$deadline->modify('-1 second')->format('Y-m-d H:i:s'),'ack'=>['version'=>ReservationTerms::VERSION]+App\Service\BillingFees::assess('bv_family',5)];$w=$t->startWorkers([$job]);usleep(3200000);$t->pdo->commit();$r=$t->finishWorkers($w);$t->assert(!$r[0]['ok']&&$r[0]['error']==='cutoff_passed'&&(int)$t->pdo->query('SELECT version FROM reservations')->fetchColumn()===1);});
$t->test('B5 activation preserves earlier food acceptance without inventing new consent',function($t){$t->pdo->exec("UPDATE settings SET svalue='disabled' WHERE skey='policy_profile'");$b=b4book($t);$original=App\Service\PreorderService::read($t->pdo,(int)$b['r']['id']);App\Service\ReservationPolicySchema::prepare($t->pdo);$p=Policies::read($t->pdo,(int)$b['r']['id']);$t->assert($p['accepted_json']===null&&$p['accepted_at']===null&&App\Service\PreorderService::read($t->pdo,(int)$b['r']['id'])===$original);App\Service\ReservationPolicySchema::prepare($t->pdo);$t->assert(Policies::read($t->pdo,(int)$b['r']['id'])===$p);});
$t->test('B5 actual receipt racing cancellation cannot lose or fabricate paid base',function($t){$b=b4book($t);$a=b4actor($t);$id=(int)$b['r']['id'];$q=(new BillingService($t->pdo,new BookingClock($t->pdo)))->quote($a,$id);$jobs=[['op'=>'billing','actor'=>$a,'id'=>$id,'action'=>'advance','revision'=>$q['revision'],'key'=>'33333333-3333-3333-3333-333333333333','data'=>['amount_cents'=>50000,'method'=>'cash','reason'=>'Actual receipt cancellation race']],['op'=>'policy_cancel','id'=>$id,'when'=>$t->date.' 09:00:00']];$t->finishWorkers($t->startWorkers($jobs));$p=Policies::read($t->pdo,$id);$money=(new Policies($t->pdo,new BookingClock($t->pdo)))->balances($id);$t->assert($p['status']==='cancelled'&&$p['forfeited_base_cents']===$money['net_base_cents']&&in_array($money['net_base_cents'],[0,50000],true));});
$t->test('B5 Any-room replacement uses selected table fees rather than filter name',function($t){$b=b4book($t);[$s,$token]=b4link($t,$b);$ack=['version'=>ReservationTerms::VERSION]+App\Service\BillingFees::assess('bv_family',5);$r=$s->modify($b['r']['code'],$token,1,$t->date,'13:00',5,'any',null,null,'',$ack);$t->assert($r['version']===2&&$r['room']['code']==='bv_family');});
$t->finish();
